import React, { useState, useMemo } from 'react';
import { LedgerEngine, formatINR } from '../utils/LedgerEngine';
import { Search, ChevronLeft, ChevronRight, Calendar } from 'lucide-react';

const CATEGORY_COLORS = {
  'Revenue': '#14B8A6',
  'Expenses': '#EF4444',
  'GST': '#C9A84C',
  'Salary': '#3B82F6',
  'Loan': '#0B1426',
  'Other': '#64748B'
};

function TransactionList({ period }) {
  const [activeFilter, setActiveFilter] = useState('All');
  const [searchTerm, setSearchTerm] = useState('');
  const [page, setPage] = useState(1);
  const pageSize = 15;

  const filteredTransactions = useMemo(() => {
    let txs = LedgerEngine.getFilteredTransactions('Full Year');
    
    if (activeFilter !== 'All') {
      txs = txs.filter(t => t.category === activeFilter || (activeFilter === 'Revenue' && t.type === 'Credit') || (activeFilter === 'Expenses' && t.type === 'Debit'));
    }
    
    if (searchTerm) {
      txs = txs.filter(t => t.narration.toLowerCase().includes(searchTerm.toLowerCase()) || t.ref.toLowerCase().includes(searchTerm.toLowerCase()));
    }

    return txs;
  }, [activeFilter, searchTerm]);

  const totalPages = Math.ceil(filteredTransactions.length / pageSize);
  const paginatedTxs = filteredTransactions.slice((page - 1) * pageSize, page * pageSize);

  const maxBalance = 8000000;

  const getCatClass = (cat) => {
    const map = {
      'Revenue': 'cat-revenue',
      'Salary': 'cat-salary',
      'Rent': 'cat-rent',
      'GST': 'cat-gst',
      'Vendor': 'cat-vendor',
      'Utility': 'cat-utility',
      'Bank': 'cat-bank',
      'Loan': 'cat-loan',
      'Tax': 'cat-tax',
      'Capex': 'cat-capex',
      'Freight': 'cat-freight'
    };
    return map[cat] || 'cat-gst';
  };

  return (
    <div className="txn-wrap">
      <div className="txn-toolbar">
        <div className="txn-filters">
          {['All', 'Revenue', 'Expenses', 'GST', 'Salary', 'Loan'].map(f => (
            <button
              key={f}
              onClick={() => { setActiveFilter(f); setPage(1); }}
              className={`filter-chip ${activeFilter === f ? 'active' : ''}`}
            >
              {f}
            </button>
          ))}
        </div>
        
        <div className="txn-search">
          <Search size={16} color="var(--text-muted)" />
          <input 
            type="text" 
            placeholder="Search transactions..." 
            value={searchTerm} 
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      <table className="txn-table">
        <thead>
          <tr>
            <th>Date</th>
            <th>Description</th>
            <th>Category</th>
            <th style={{ textAlign: 'right' }}>Amount</th>
            <th style={{ textAlign: 'right' }}>Balance</th>
          </tr>
        </thead>
        <tbody>
          {paginatedTxs.map((t, i) => {
            const d = new Date(t.date);
            const day = d.getDate();
            const month = d.toLocaleString('default', { month: 'short' });
            const balance = 4500000 + (i * 100000); // Simulated balance
            
            return (
              <tr key={t.id}>
                <td>
                  <div style={{ display: 'flex', flexDirection: 'column' }}>
                    <span className="txn-date-day">{day}</span>
                    <span className="txn-date-month">{month}</span>
                  </div>
                </td>
                <td>
                  <div style={{ display: 'flex', flexDirection: 'column' }}>
                    <span className="txn-desc">{t.narration}</span>
                    <span className="txn-ref">REF: {t.ref}</span>
                  </div>
                </td>
                <td>
                  <span className={`cat-pill ${getCatClass(t.category)}`}>
                    {t.category || 'Other'}
                  </span>
                </td>
                <td style={{ textAlign: 'right' }}>
                  <span className={t.type === 'Credit' ? 'amount-credit' : 'amount-debit'}>
                    {t.type === 'Credit' ? '+' : '-'}{formatINR(t.amount)}
                  </span>
                </td>
                <td style={{ textAlign: 'right' }}>
                  <span className="amount-balance">{formatINR(balance)}</span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>

      <div className="txn-pagination">
        <span className="page-info">Showing page {page} of {totalPages}</span>
        <div className="page-btns">
          <button 
            className="page-btn"
            disabled={page === 1} 
            onClick={() => setPage(page - 1)}
          >
            <ChevronLeft size={16} />
          </button>
          {[...Array(Math.min(totalPages, 5))].map((_, idx) => (
            <button 
              key={idx}
              className={`page-btn ${page === idx + 1 ? 'active' : ''}`}
              onClick={() => setPage(idx + 1)}
            >
              {idx + 1}
            </button>
          ))}
          <button 
            className="page-btn"
            disabled={page === totalPages} 
            onClick={() => setPage(page + 1)}
          >
            <ChevronRight size={16} />
          </button>
        </div>
      </div>
    </div>
  );
}

export default TransactionList;
